def run_workflow(task, tools):
    req = parse_question(task['question'])
    calls = []
    try:
        if req['query']:
            calls.append('search_notes')
            ids = tools['search_notes']['fn'](req['query'], 1)
            return str(ids[0]), calls
        closes = []
        for d in req['dates']:
            calls.append('get_close')
            closes.append(tools['get_close']['fn'](req['ticker'], d))
        if len(closes) == 1:
            return f'{closes[0]:.2f}', calls
        calls.append('pct_change')
        change = tools['pct_change']['fn'](closes[0], closes[1])
        return f'{change:.2f}%', calls
    except Exception:
        return None, calls

